export function responsiveImage(src: string, overview = false) {
  return {
    srcSet: variants[src],
    sizes: overview
      ? "(min-width: 1024px) 33vw, (min-width: 768px) 50vw, 100vw"
      : "(min-width: 1024px) 50vw, 100vw",
  };
}
